import axios from "axios";
import MaterialTable from "material-table";
import React, { Component } from "react";

import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import Typography from "@material-ui/core/Typography";
import Breadcrumbs from "@material-ui/core/Breadcrumbs";
import Link from "@material-ui/core/Link";
import Card from "@material-ui/core/Card";
import { changePage } from "../../actions/pageActions";
import Checkbox from "@material-ui/core/Checkbox";
import Tooltip from "@material-ui/core/Tooltip";

import CardContent from "@material-ui/core/CardContent";
class AccessConfiguration extends Component {
  state = {
    rowData1: [],
    tableLoaded: true
  };

  componentDidMount() {
    this.retrieveFromDb();
  }

  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData1: state.rowData1
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData1 = res.data.filter((x, index) => {
          return x.deletedAt == null;
        });
        rowData1 = rowData1.map((x, index) => {
          return {
            clientId: x._id,
            client: x.name,
            edit: <Checkbox color="primary" onChange={this.showDeletes} />,
            view: <Checkbox color="primary" onChange={this.showDeletes} />
          };
        });

        this.setState(state => ({
          tableLoaded: true,
          rowData1
        }));
      })
      .catch(err => console.log(err));
  };

  onPageChangeClick = (navType, page, objId) => {
    const pageDetail = {
      navType,
      page,
      objId
    };
    //this.props.changePage(pageDetail);
  };

  render() {
    return (
      <div>
        <Card className="mb-2">
          <CardContent>
            <Breadcrumbs
              style={{
                display: "flex",
                justifyContent: "center"
              }}
            >
              <Link
                color="inherit"
                href="/"
                onClick={this.onPageChangeClick("OpsNav", "AccessSetup", 0)}
              >
                Create New Access
              </Link>

              <Typography color="textPrimary">
                User Access Configuration
              </Typography>
            </Breadcrumbs>
          </CardContent>
        </Card>

        <Card className="mb-2">
          <CardContent>Access ID: {this.props.page.page.objId}</CardContent>
        </Card>

        <MaterialTable
          columns={[
            { title: "Client", field: "client" },
            { title: "Client Id", field: "clientId" },
            { title: "Add/Edit/Delete Access", field: "edit" },
            { title: "View Access", field: "view" }
          ]}
          data={this.state.rowData1}
          title="Client Based Access"
        />
        <div className="mb-2"></div>
        <MaterialTable
          columns={[
            { title: "Description", field: "desc" },
            { title: "Add/Edit/Delete Access", field: "edit" },
            { title: "View Access", field: "view" }
          ]}
          options={{
            search: false,
            pageSize: 2,
            paging: false
          }}
          data={[
            {
              desc: "Clients",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Client Details",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Self Created Clients and Details",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            }
          ]}
          title="Client Object Access "
        />
        <div className="mb-2">hello</div>
        <MaterialTable
          columns={[
            { title: "Description", field: "desc" },
            { title: "Add/Edit/Delete Access", field: "edit" },
            { title: "View Access", field: "view" }
          ]}
          options={{
            search: false,
            pageSize: 3,
            paging: false
          }}
          data={[
            {
              desc: "Process Groups",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Process Group Details",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Self Created Process Groups and Details",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            }
          ]}
          title="Process Group Object Access"
        />
        <div className="mb-2"></div>
        <MaterialTable
          columns={[
            { title: "Description", field: "desc" },
            { title: "Add/Edit/Delete Access", field: "edit" },
            { title: "View Access", field: "view" }
          ]}
          options={{
            search: false,
            pageSize: 3,
            paging: false
          }}
          data={[
            {
              desc: "Items (Sourced Items)",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Item (Sourced Items) Details",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Self Created Items (Sourced Items) and Details",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            }
          ]}
          title="Item Object Access"
        />
        <div className="mb-2"></div>
        <MaterialTable
          columns={[
            { title: "Description", field: "desc" },
            { title: "Add/Edit/Delete Access", field: "edit" },
            { title: "View Access", field: "view" }
          ]}
          options={{
            search: false,
            pageSize: 6,
            paging: false
          }}
          data={[
            {
              desc: "Self Created Processes",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Process: Machining",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Process: Casting",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Process: Assembly",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },

            {
              desc: "Process: PCBs",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            },
            {
              desc: "Process: ICs",
              edit: <Checkbox color="primary" onChange={this.showDeletes} />,
              view: <Checkbox color="primary" onChange={this.showDeletes} />
            }
          ]}
          title="Process Object Access"
        />
      </div>
    );
  }
}

const mapStateToProps = state => ({
  page: state.page
});

export default connect(mapStateToProps, { changePage })(AccessConfiguration);
